func newClassicMacosConfigProfilesDeleteCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagYes    bool
		flagDryRun bool
		flagName   string
		fromFile   string
	)

	cmd := &cobra.Command{
		Use:   "delete [<id>]",
		Short: "Delete a os_x_configuration_profile",
		Example: `  # Delete a os_x_configuration_profile (with confirmation)
  jamf-cli pro classic-macos-config-profiles delete 1

  # Delete by name
  jamf-cli pro classic-macos-config-profiles delete --name "Example" --yes

  # Delete without confirmation prompt
  jamf-cli pro classic-macos-config-profiles delete 1 --yes`,
		Annotations: map[string]string{"jamf:destructive": "true", "jamf:api": "pro-classic", "jamf:gateway-privileges": "configuration-profiles:delete"},
		Args:        cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			// --from-file: bulk delete from a file of IDs or names
			if fromFile != "" {
				entries, err := readDeleteFile(fromFile)
				if err != nil {
					return fmt.Errorf("reading --from-file: %w", err)
				}
				if len(entries) == 0 {
					return fmt.Errorf("--from-file %q: no entries found", fromFile)
				}
				type bulkEntry struct{ id, label string }
				bulk := make([]bulkEntry, 0, len(entries))
				noInputBulk, _ := cmd.Flags().GetBool("no-input")
				for _, entry := range entries {
					if isNumericID(entry) {
						if entry == "0" {
							return fmt.Errorf("--from-file: ID 0 is not valid (Jamf Pro uses 0 as a sentinel value)")
						}
						bulk = append(bulk, bulkEntry{id: entry, label: entry})
					} else {
						var resolvedID string
						if resolvedID == "" {
							id, err := resolveClassicNameToIDForApply(reqCtx, ctx.Client, "osxconfigurationprofiles", "osxconfigurationprofiles", entry, "update", noInputBulk)
							if err != nil {
								return fmt.Errorf("resolving %q: %w", entry, err)
							}
							resolvedID = id
						}
						if resolvedID == "" {
							return fmt.Errorf("no os_x_configuration_profile found matching %q", entry)
						}
						bulk = append(bulk, bulkEntry{id: resolvedID, label: entry})
					}
				}
				// Deduplicate resolved IDs to avoid double-delete errors.
				{
					seen := make(map[string]bool, len(bulk))
					deduped := bulk[:0]
					for _, e := range bulk {
						if !seen[e.id] {
							seen[e.id] = true
							deduped = append(deduped, e)
						}
					}
					bulk = deduped
				}
				if flagDryRun {
					for _, e := range bulk {
						fmt.Fprintf(os.Stderr, "[dry-run] Would delete os_x_configuration_profile %q (id: %s)\n", e.label, e.id)
					}
					return nil
				}
				if !flagYes {
					if noInputBulk {
						return fmt.Errorf("destructive operation requires --yes when --no-input is set")
					}
					fmt.Fprintf(os.Stderr, "⚠️  This will delete %d osxconfigurationprofiles. Type 'yes' to confirm: ", len(bulk))
					var confirm string
					fmt.Scanln(&confirm)
					if confirm != "yes" {
						return fmt.Errorf("aborted")
					}
				}
				if err := cooldown.Enforce(ctx.ProfileName, noInputBulk, ctx.DestructiveCooldown); err != nil {
					return err
				}
				var okCount, failCount int
				var firstErr error
				for _, e := range bulk {
					delPath := fmt.Sprintf("/JSSResource/osxconfigurationprofiles/id/%s", url.PathEscape(e.id))
					resp, err := ctx.Client.Do(reqCtx, "DELETE", delPath, nil)
					if err != nil {
						fmt.Fprintf(os.Stderr, "delete os_x_configuration_profile %q (id: %s) failed: %v\n", e.label, e.id, err)
						if firstErr == nil {
							firstErr = err
						}
						failCount++
						continue
					}
					resp.Body.Close()
					if resp.StatusCode == http.StatusNoContent || resp.StatusCode == http.StatusOK {
						fmt.Fprintf(os.Stderr, "Deleted os_x_configuration_profile %q (id: %s)\n", e.label, e.id)
						okCount++
					} else {
						fmt.Fprintf(os.Stderr, "delete os_x_configuration_profile %q (id: %s) failed: HTTP %d\n", e.label, e.id, resp.StatusCode)
						if firstErr == nil {
							firstErr = fmt.Errorf("HTTP %d", resp.StatusCode)
						}
						failCount++
					}
				}
				cooldown.Record(ctx.ProfileName)
				return batchDeleteError(cmd, okCount, failCount, firstErr, "osxconfigurationprofiles deletes")
			}

			// Resolve ID from --name or positional arg
			var resolvedID string
			noInput, _ := cmd.Flags().GetBool("no-input")
			if flagName != "" {
				id, err := resolveClassicNameToIDForApply(reqCtx, ctx.Client, "osxconfigurationprofiles", "osxconfigurationprofiles", flagName, "update", noInput)
				if err != nil {
					return err
				}
				if id == "" {
					return fmt.Errorf("no os_x_configuration_profile found with name %q", flagName)
				}
				resolvedID = id
			} else if len(args) > 0 {
				resolvedID = args[0]
			} else {
				return fmt.Errorf("provide an <id> argument or --name")
			}

			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would delete os_x_configuration_profile %s\n", resolvedID)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("destructive operation requires --yes when --no-input is set")
				}
				fmt.Fprintf(os.Stderr, "This will delete os_x_configuration_profile %s. Type 'yes' to confirm: ", resolvedID)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			if err := cooldown.Enforce(ctx.ProfileName, noInput, ctx.DestructiveCooldown); err != nil {
				return err
			}
			path := fmt.Sprintf("/JSSResource/osxconfigurationprofiles/id/%s", url.PathEscape(resolvedID))

			resp, err := ctx.Client.Do(reqCtx, "DELETE", path, nil)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			if resp.StatusCode == http.StatusNoContent || resp.StatusCode == http.StatusOK {
				cooldown.Record(ctx.ProfileName)
				fmt.Fprintln(os.Stderr, "Deleted successfully")
				return nil
			}

			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")
	cmd.Flags().StringVar(&flagName, "name", "", "Look up os_x_configuration_profile by name")
	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to file listing IDs or names to delete (one per line, # comments ignored)")
	cmd.MarkFlagsMutuallyExclusive("from-file", "name")

	return cmd
}

func newClassicMacosConfigProfilesApplyCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		fromFile                string
		flagYes                 bool
		flagDryRun              bool
		flagScaffold            bool
		flagSet                 []string
		flagMobileconfigFile    string
		flagCustomPayloadFiles  []string
		flagCustomPayloadDomain string
		flagName                string
	)

	cmd := &cobra.Command{
		Use:         "apply",
		Short:       "Create or replace a os_x_configuration_profile by name",
		Annotations: map[string]string{"jamf:api": "pro-classic", "jamf:gateway-privileges": "configuration-profiles:create,configuration-profiles:read,configuration-profiles:update"},
		Long: `Create or replace a os_x_configuration_profile. Reads XML from --from-file, --set or stdin.

The name field in the input XML is used to check if the resource already
exists. If it does, the resource is replaced (with confirmation).
If not, a new resource is created.

Body fields are derived from the Classic API spec (schema "os_x_configuration_profile").
Run with --scaffold to print a complete XML template.
The template populates every optional section with one specimen entry,
including references whose <id> points at nothing on your instance — delete
the sections you do not need. A dangling reference is answered with a 500.
Optional sections: general, scope, self_service

Allowed values:
  general.distribution_method: Install Automatically | Make Available in Self Service
  general.level: computer | user

The Classic API does not reject an out-of-range value — it substitutes
its default silently — so --set refuses one rather than letting it through.

Credential fields (--from-file only, never --set): self_service.security.password`,
		Example: `  # Apply a os_x_configuration_profile from an XML file
  jamf-cli pro classic-macos-config-profiles apply --from-file os_x_configuration_profile.xml

  # Apply from stdin
  cat os_x_configuration_profile.xml | jamf-cli pro classic-macos-config-profiles apply

  # Apply without replacement confirmation
  jamf-cli pro classic-macos-config-profiles apply --from-file os_x_configuration_profile.xml --yes`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if flagScaffold {
				return printClassicScaffold(bodySpecClassicMacosConfigProfiles)
			}
			reqCtx := cmd.Context()

			// Read input
			data, err := readApplyInput(fromFile)

			anyFileFlag := flagMobileconfigFile != "" || len(flagCustomPayloadFiles) > 0

			if flagMobileconfigFile != "" && len(flagCustomPayloadFiles) > 0 {
				return fmt.Errorf("--mobileconfig-file and --custom-payload-file are mutually exclusive")
			}
			if flagCustomPayloadDomain != "" && len(flagCustomPayloadFiles) != 1 {
				return fmt.Errorf("--custom-payload-domain requires exactly one --custom-payload-file")
			}
			if err != nil && !anyFileFlag {
				return err
			}
			err = nil

			// Inject file fields before name extraction so name-fallback (if any)
			// can populate <general><name> for lookup.

			if flagName != "" {
				data = setClassicGeneralName(data, "os_x_configuration_profile", flagName)
			}
			if len(flagCustomPayloadFiles) > 0 {
				var mcBytes []byte
				mcBytes, err = buildCustomPayloadMobileconfig(flagCustomPayloadFiles, flagCustomPayloadDomain)
				if err != nil {
					return err
				}
				data, err = injectClassicFileFields(data, "os_x_configuration_profile", []classicFileFieldSpec{
					{FileBytes: mcBytes, FileNameHint: flagCustomPayloadFiles[0], ParentPath: []string{"general"}, LeafName: "payloads", Encoding: "xml-cdata", NameFallback: "strip-ext"},
				})
			} else {
				data, err = injectClassicFileFields(data, "os_x_configuration_profile", []classicFileFieldSpec{
					{FilePath: flagMobileconfigFile, ParentPath: []string{"general"}, LeafName: "payloads", Encoding: "xml-cdata", NameFallback: "strip-ext"},
				})
			}

			if err != nil {
				return err
			}

			// Extract name: for fetch-merge-put resources, --name is the primary
			// input (body typically empty); fall back to XML name if flag absent.
			var name string

			name, err = extractClassicName(data, "os_x_configuration_profile")
			if err != nil {
				return err
			}

			// Check if resource exists by name (read-only, runs even in dry-run)
			noInput, _ := cmd.Flags().GetBool("no-input")
			id, err := resolveClassicNameToIDForApply(reqCtx, ctx.Client, "osxconfigurationprofiles", "osxconfigurationprofiles", name, "update", noInput)
			if err != nil {
				return err
			}

			if id == "" {
				// Not found — create (not allowed for fetch-merge-put resources)

				if flagDryRun {
					fmt.Fprintf(os.Stderr, "[dry-run] Would create os_x_configuration_profile %q\n", name)
					return nil
				}

				data = normalizeClassicProfilePayloadsForSend(data)
				resp, err := ctx.Client.Do(reqCtx, "POST", "/JSSResource/osxconfigurationprofiles/id/0", bytes.NewReader(data))
				if err != nil {
					return err
				}
				defer resp.Body.Close()
				respBody, readErr := io.ReadAll(resp.Body)
				if readErr != nil {
					return readErr
				}
				verifyClassicProfileStored(reqCtx, ctx.Client, "osxconfigurationprofiles", classicCreatedResourceID(respBody), data)
				fmt.Fprintf(os.Stderr, "Created os_x_configuration_profile %q\n", name)
				return ctx.Output.PrintRaw(respBody)

			}

			// Found — replace
			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would replace os_x_configuration_profile %q (id: %s)\n", name, id)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("os_x_configuration_profile %q already exists (id: %s); use --yes to replace when --no-input is set", name, id)
				}
				fmt.Fprintf(os.Stderr, "os_x_configuration_profile %q already exists (id: %s) and will be replaced. Type 'yes' to confirm: ", name, id)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			// Preserve existing PayloadUUID and PayloadIdentifier.
			existingPayload := fetchClassicProfilePayloadPlist(reqCtx, ctx.Client, "osxconfigurationprofiles", id)
			data = injectClassicProfilePayloadUUIDs(data, existingPayload)
			data = injectClassicRedeployOnUpdate(data)
			data = normalizeClassicProfilePayloadsForSend(data)

			updatePath := fmt.Sprintf("/JSSResource/osxconfigurationprofiles/id/%s", url.PathEscape(id))
			resp, err := ctx.Client.Do(reqCtx, "PUT", updatePath, bytes.NewReader(data))
			if err != nil {
				return err
			}
			verifyClassicProfileStored(reqCtx, ctx.Client, "osxconfigurationprofiles", id, data)

			defer resp.Body.Close()
			fmt.Fprintf(os.Stderr, "Replaced os_x_configuration_profile %q (id: %s)\n", name, id)
			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to XML input file (or pipe XML to stdin)")
	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print an XML body template for this resource and exit")
	cmd.Flags().StringArrayVar(&flagSet, "set", nil, "Set a body field in dot notation (key=value, repeatable). Builds the whole body, so it cannot be combined with --from-file")
	_ = cmd.RegisterFlagCompletionFunc("set", func(_ *cobra.Command, _ []string, _ string) ([]string, cobra.ShellCompDirective) {
		return []string{"general.category.id=", "general.category.name=", "general.description=", "general.distribution_method=", "general.id=", "general.level=", "general.name=", "general.payloads=", "general.redeploy_on_update=", "general.site.id=", "general.site.name=", "general.user_removable=", "general.uuid=", "scope.all_computers=", "scope.all_jss_users=", "self_service.feature_on_main_page=", "self_service.force_users_to_view_description=", "self_service.install_button_text=", "self_service.notification=", "self_service.notification_message=", "self_service.notification_subject=", "self_service.security.removal_disallowed=", "self_service.self_service_description=", "self_service.self_service_display_name=", "self_service.self_service_icon.data=", "self_service.self_service_icon.id=", "self_service.self_service_icon.uri="}, cobra.ShellCompDirectiveNoSpace
	})

	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt when replacing")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")

	cmd.Flags().StringVar(&flagMobileconfigFile, "mobileconfig-file", "", "Path to a .mobileconfig file; contents are CDATA-wrapped into <general><payloads>")
	cmd.Flags().StringArrayVar(&flagCustomPayloadFiles, "custom-payload-file", nil, "Path to a preference plist (XML or binary); wrapped into a com.apple.ManagedClient.preferences payload (repeatable; mutually exclusive with --mobileconfig-file)")
	cmd.Flags().StringVar(&flagCustomPayloadDomain, "custom-payload-domain", "", "Preference domain override (inferred from filename by default; only valid with a single --custom-payload-file)")
	cmd.Flags().StringVar(&flagName, "name", "", "Profile name (overrides filename-based default when using --custom-payload-file)")

	return cmd
}
